def f(n: int, adjacency_list: List[Tuple[int, int, List[int]]]) -> int:
    graph = {u: [] for u in range(1, n + 1)}
    for u, k, *v in adjacency_list:
        for v_i in v:
            graph[u].append(v_i)  # Add bidirectional edges
            graph[v_i].append(u)

    min_distance = [float('inf')] * (n + 1)
    min_distance[1] = 0
    visited = {1}
    for _ in range(n - 1):
        for v in visited:
            for u in graph[v]:
                if u not in visited and min_distance[u] == float('inf'):
                    min_distance[u] = min_distance[v] + 1
                    visited.add(u)

    return sum(min_distance[1:])


